## 🛠️ 해결 방법

**1. 즉시 조치 (임시)**
```javascript
// search-llm.js:118 근처 수정
const parseExplanations = (data) => {
  try {
    // 줄바꿈, 따옴표 이스케이프 처리
    const cleanedData = data
      .trim()
      .replace(/[\n\r]/g, ' ')
      .replace(/(?<!\\)"/g, '\\"'); // 이스케이프되지 않은 따옴표 처리

    return JSON.parse(cleanedData);
  } catch(e) {
    console.error('JSON Parse Error:', {
      message: e.message,
      position: e.message.match(/position (\d+)/)?.[1],
      rawData: data.substring(0, 100) // 처음 100자만 로깅
    });
    return null; // 폴백 로직 트리거
  }
};
```

