### 1️⃣ **즉시 조치** - 폴백 로직 추가
```javascript
// search-llm.js (parseExplanations 함수)
function parseExplanations(rawResponse) {
  try {
    // 기존 파싱 시도
    return JSON.parse(rawResponse);
  } catch (error) {
    console.warn('JSON 파싱 실패:', error.message);
    // 폴백: 유효한 JSON이 될 때까지 정제
    const cleaned = rawResponse
      .replace(/[\r\n]/g, '') // 줄바꿈 제거
      .replace(/,\s*]/g, ']') // 끝의 쉼표 제거
      .replace(/,\s*}/g, '}');

    try {
      return JSON.parse(cleaned);
    } catch {
      // 최후의 수단: 유사도 기반 매칭으로 폴백
      return ['유사도 기반 매칭'];
    }
  }
}
```

