### **1️⃣ 근본 원인 해결: VectorSearch의 Bedrock 스로틀링 제어**
```javascript
// file: VectorSearchFunction/index.js
const invokeClaude = async (prompt, retries = 3) => {
  for (let i = 0; i < retries; i++) {
    try {
      return await bedrockClient.invokeModel(...);
    } catch (error) {
      if (error.$metadata?.httpStatusCode === 429) {
        const backoffMs = Math.pow(2, i) * 1000 + Math.random() * 1000;
        console.log(`Throttled. Retrying in ${backoffMs}ms...`);
        await new Promise(resolve => setTimeout(resolve, backoffMs));
      } else throw error;
    }
  }
};
```

